using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class BellEnd : LayoutBase
{
    public BellEnd()
    {
        Name = LayoutNamesEnums.BellEnd;
        Description = "Bell End is set on an imaginary ex-GWR branch line in the rolling countryside of north Worcestershire. The branch starts at Stourbridge Junction and heads south towards the village of Top Hagley, where it passes under the Birmingham Road and serves a single platform and a small goods yard for the cattle market. It then skirts Hagley Hall and Park before following the route of what is now the A491 Feeder Road, where a small station with a single track platform and simple goods yard serves the twin villages of Holly Cross and Clent, and continues on to the hamlet of Bell End, where a short goods only line runs to a small dairy. Passenger trains are made up of a small prairie and B set, a 14xx and auto coach, or an ex-GWR railcar, shuttling between Stourbridge and Bell End, usually with empty milk tanks on the rear. The branch sees a daily goods train arriving around lunchtime, again in the hands of a small prairie or pannier tank, and an evening milk train to Birmingham. There is also a private siding north of Bell End serving the Government Pipeline and Storage System, a secret fuel supply network created during the Second World War which included a branch from Ellesmere Port to Avonmouth; this siding is believed to be a back up to the main siding on the original Severn Valley line at Stourport on Severn.";
    }
}
